  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "A fundamental new classification of electronic matter, with experimentally established protected edge transport and lasting consequences across condensed matter physics.",
        "attribution": "Kane and Mele supplied the defining quantum spin Hall theory; Molenkamp led a decisive experimental realization. The candidate's scope necessarily leaves further important experimental contributors outside the proposed trio.",
        "maturity": "The underlying physics has been reproduced, generalized, and incorporated into a broad quantitative field over two decades.",
        "uncertainties": [
          "The optimal boundary between quantum spin Hall physics, three-dimensional topological insulators, and later related discoveries requires careful prize-definition work."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated materials quantitatively tractable and transformed the interpretation of spectral and phase-transition data.",
        "attribution": "Georges, Kotliar, and Vollhardt represent the central conceptual and methodological development, though the development drew on an extensive wider community.",
        "maturity": "Its predictions and computational framework have been tested for decades in transition-metal compounds, f-electron systems, and modern spectroscopy.",
        "uncertainties": [
          "Credit for the intellectual antecedents and subsequent practical implementations is distributed across a larger field."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions established a striking topological state in real materials, with emergent electrodynamics and a major new direction in magnetism.",
        "attribution": "Pfleiderer and Tokura are highly visible leaders of the key experimental discoveries and development of the field.",
        "maturity": "The textures, their dynamics, and their transport signatures have been independently observed across multiple chiral magnetic systems.",
        "uncertainties": [
          "The division of priority among the several early experimental and theoretical groups needs detailed historical assessment."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance and MgO-based junctions joined a clear quantum transport effect to enormously consequential magnetic-memory technology.",
        "attribution": "Miyazaki and Moodera were pivotal in early room-temperature TMR, while Parkin was central to giant coherent MgO-barrier TMR and its device impact.",
        "maturity": "The effect is robustly reproduced, theoretically understood in terms of spin-dependent tunnelling, and technologically deployed.",
        "uncertainties": [
          "The historical boundary between the early TMR discovery and the later MgO-junction breakthrough must be specified precisely."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Moiré flat bands created an exceptionally controllable platform for correlated and topological quantum matter, with genuinely surprising phenomenology.",
        "attribution": "Bistritzer and MacDonald provided the influential flat-band theory, and Jarillo-Herrero's group supplied the seminal experimental realization.",
        "maturity": "The principal correlated phases have been widely reproduced and the platform has expanded rapidly to many moiré materials.",
        "uncertainties": [
          "The discovery is comparatively recent, and the ultimate unifying account of the many observed phases remains incomplete."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Henry J. Snaith",
        "Nam-Gyu Park",
        "Tsutomu Miyasaka"
      ],
      "assessment": {
        "nobel_worthiness": "Metal-halide perovskites changed the landscape of photovoltaic materials through remarkable optoelectronic performance and unusually rapid device progress.",
        "attribution": "Miyasaka, Park, and Snaith are central figures in the emergence, efficiency advance, and recognition of perovskite solar cells.",
        "maturity": "The physical material class and its high photovoltaic efficiency are firmly established, with substantial independent reproduction.",
        "uncertainties": [
          "Long-term operational stability, scalable manufacture, and the attribution of the many interlocking materials and device advances remain concerns."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B049",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps supplied a powerful materials concept for controlling light and stimulated a durable experimental and technological field.",
        "attribution": "John and Yablonovitch made foundational proposals, while Joannopoulos made central theoretical contributions to understanding and designing photonic crystals.",
        "maturity": "The phenomena are thoroughly established in diverse platforms and have informed both basic optical physics and device design.",
        "uncertainties": [
          "The credit boundary between the original photonic-crystal concept, later fabrication advances, and related cavity-photonics work is broad."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "A. Peter Young",
        "Bertrand I. Halperin",
        "David R. Nelson"
      ],
      "assessment": {
        "nobel_worthiness": "Defect-mediated two-dimensional melting and the hexatic phase gave a profound account of how order is lost in reduced dimensions.",
        "attribution": "Halperin, Nelson, and Young made the defining theoretical contributions to the modern two-dimensional melting framework.",
        "maturity": "Its distinctive predictions have motivated extensive simulations and experiments over many decades.",
        "uncertainties": [
          "Experimental systems can show disorder, finite-size, and nonequilibrium effects that complicate a clean comparison with the ideal theory."
        ]
      }
    }
  ]
}
